function transformInsert(a, b) {
  if (b.type === "del") {
    return a.pos <= b.pos ? a : { ...a, pos: a.pos - 1 };
  }
  const aFirst = a.pos < b.pos || (a.pos === b.pos && a.site < b.site);
  return aFirst ? a : { ...a, pos: a.pos + 1 };
}

const ins = (doc, o) => doc.slice(0, o.pos) + o.ch + doc.slice(o.pos);
const a = { type: "ins", pos: 2, ch: "X", site: "bob" };
const b = { type: "ins", pos: 2, ch: "Y", site: "alice" };
ins(ins("abc", b), transformInsert(a, b)); // "abYXc"
ins(ins("abc", a), transformInsert(b, a)); // "abYXc"
```
